/* Only exact, single-course public rows can produce provisional course-credit matches. */
var PublicTransferChecks=(()=>{
 function equivalentRecords(records,rows,destination){const out=[],evidence=[],seen=new Set();for(const c of records){if(!PublicAudit.passed(c)||c.units!=='Quarter')continue;const term=String(c.term||'').match(/\b(Winter|Spring|Summer|Autumn|Fall)\b/i),year=String(c.term||'').match(/\b(20\d{2})\b/);if(!term||!year)continue;const season=term[1][0].toUpperCase()+term[1].slice(1).toLowerCase();for(const r of rows){if(!r.exactSimple||r.reviewRequired||r.obsolete||r.campusRestrictionsRaw||r.sourceCodes?.length!==1||r.destinationCodes?.length!==1||r.sourceCredits?.length!==1||r.destinationCredits?.length!==1)continue;if(PublicAudit.canonical(r.destinationInstitution)!==PublicAudit.canonical(destination))continue;if(r.sourceInstitution!==c.institution&&!r.sourceCampuses?.includes(c.institution))continue;if(PublicAudit.norm(r.sourceCodes[0])!==PublicAudit.norm(c.code)||+r.sourceCredits[0]!==+c.credits)continue;if(!TransferGuideCore.applicability(r,+year[1],season).startsWith('Within'))continue;const id=PublicAudit.key(c)+'|'+r.id;if(seen.has(id))continue;seen.add(id);out.push({...c,code:r.destinationCodes[0],institution:PublicAudit.canonical(destination),units:'Quarter',credits:r.destinationCredits[0],sourceEquivalent:true,sourceOriginKey:PublicAudit.key(c),sourceEvidenceId:r.id});evidence.push({id:r.id,from:c.institution+' · '+c.code,to:destination+' · '+r.destinationCodes[0],source:r.source,term:c.term,scope:r.majorApplicability})}}return{records:out,evidence}}
 return{equivalentRecords};
})();if(typeof module!=='undefined')module.exports=PublicTransferChecks;
